#!/usr/bin/env python3
"""Test actual multiplayer round capture/restore against stale legacy playlist.
The server/game structs model only helper-touched fields; this is a policy test,
not a wire-layout or device test. --omit-restore is the old-path negative control.
"""
import argparse,pathlib,subprocess,tempfile,sys
p=argparse.ArgumentParser();p.add_argument('--m32',action='store_true');p.add_argument('--sanitizers',action='store_true');p.add_argument('--omit-restore',action='store_true');p.add_argument('--cc',default='gcc');a=p.parse_args()
root=pathlib.Path(__file__).resolve().parents[1]
text=(root/'source/networking/network_server_manager.c').read_text()
start=text.index('struct network_multiplayer_round_settings\n');end=text.index('/* port: reapply the co-op settings after a won round',start)
PREFIX='#include <assert.h>\n#include <stdio.h>\n#include <stddef.h>\n#include <string.h>\ntypedef unsigned char byte,boolean;\n#define TRUE 1\n#define FALSE 0\n#define NETWORK_GAME_NAME_LENGTH 16\n#define game_engine_none 0\n#define game_engine_race 5\n#define _network_game_server_state_postgame 4\nstruct network_game_map{long version;char name[128];};\nstruct game_variant{long game_engine_index;struct{float health;long score_to_win;boolean teams;}universal_variant;char label[24];};\nstruct game_variant_options{short time_limit,friendly_fire;byte loadout,primary_weapon,secondary_weapon,no_map_weapons;};\nstruct network_game{wchar_t name[16];struct network_game_map map;struct game_variant variant;struct game_variant_options variant_options;char minimum_players;byte maximum_players,maximum_teams;short difficulty;int dynamic_state;};\nstruct network_game_server{int state;struct network_game game;};\nstatic struct game_variant ui_variant;static struct game_variant_options ui_options;static char main_map[128];static int mirrors;\n#define csmemset memset\n#define csmemcpy memcpy\nstatic void player_ui_set_game_variant(struct game_variant*v){ui_variant=*v;memset(&ui_options,0,sizeof(ui_options));mirrors++;}\nstatic void player_ui_set_game_variant_options(struct game_variant_options const*o){ui_options=*o;}\nstatic void main_set_multiplayer_map_name(char const*m){snprintf(main_map,sizeof(main_map),"%s",m);}\nstatic void stale_playlist(struct network_game_server*s){memset(s->game.name,0,sizeof(s->game.name));s->game.map.version=0;strcpy(s->game.map.name,"levels\\\\test\\\\carousel\\\\carousel");memset(&s->game.variant,0,sizeof(s->game.variant));memset(&s->game.variant_options,0,sizeof(s->game.variant_options));s->game.minimum_players=2;s->game.maximum_players=128;s->game.maximum_teams=1;s->game.difficulty=0;s->game.dynamic_state=0;}\nstatic int checks;\n#define CHECK(x) do{if(!(x)){fprintf(stderr,"FAIL %s line%d\\n",#x,__LINE__);return 1;}checks++;}while(0)\n'
CHECKS='\nstatic struct network_game_server make_room(int engine,char const *map){struct network_game_server s;memset(&s,0,sizeof(s));s.state=4;s.game.name[0]=\'G\';s.game.name[1]=\'G\';s.game.map.version=609;snprintf(s.game.map.name,sizeof(s.game.map.name),"%s",map);s.game.variant.game_engine_index=engine;strcpy(s.game.variant.label,engine==2?"Gun Game":"Other");s.game.variant.universal_variant.health=1.5f;s.game.variant.universal_variant.score_to_win=7;s.game.variant.universal_variant.teams=0;s.game.variant_options=(struct game_variant_options){15,0,1,0,0,1};s.game.minimum_players=2;s.game.maximum_players=32;s.game.maximum_teams=1;s.game.difficulty=-1;s.game.dynamic_state=123;return s;}\nint main(void){struct network_multiplayer_round_settings held;struct network_game_server s=make_room(2,"levels\\\\test\\\\bloodgulch\\\\bloodgulch");struct network_game wanted=s.game;network_game_server_capture_multiplayer_round(&s,&held);CHECK(held.captured);stale_playlist(&s);\n#ifndef OMIT_RESTORE\n network_game_server_restore_multiplayer_round(&s,&held);\n#endif\n CHECK(!strcmp(s.game.map.name,wanted.map.name));CHECK(!memcmp(&s.game.map,&wanted.map,sizeof(wanted.map)));CHECK(!memcmp(&s.game.variant,&wanted.variant,sizeof(wanted.variant)));CHECK(!memcmp(&s.game.variant_options,&wanted.variant_options,sizeof(wanted.variant_options)));CHECK(!memcmp(s.game.name,wanted.name,sizeof(wanted.name)));CHECK(s.game.minimum_players==2&&s.game.maximum_players==32&&s.game.maximum_teams==1&&s.game.difficulty==-1);CHECK(s.game.dynamic_state==0);CHECK(mirrors==1&&!memcmp(&ui_variant,&wanted.variant,sizeof(wanted.variant))&&!memcmp(&ui_options,&wanted.variant_options,sizeof(wanted.variant_options)));CHECK(!strcmp(main_map,wanted.map.name));\n /* Every supported multiplayer engine/custom settings copy is preserved. */\n for(int engine=1;engine<=5;engine++){s=make_room(engine,"levels\\\\test\\\\beavercreek\\\\beavercreek");s.game.variant.universal_variant.score_to_win=37;s.game.variant.universal_variant.teams=1;s.game.variant_options.time_limit=19;s.game.maximum_players=128;s.game.maximum_teams=2;wanted=s.game;network_game_server_capture_multiplayer_round(&s,&held);stale_playlist(&s);network_game_server_restore_multiplayer_round(&s,&held);CHECK(!memcmp(&s.game.map,&wanted.map,sizeof(wanted.map)));CHECK(!memcmp(&s.game.variant,&wanted.variant,sizeof(wanted.variant)));CHECK(!memcmp(&s.game.variant_options,&wanted.variant_options,sizeof(wanted.variant_options)));CHECK(s.game.maximum_players==128&&s.game.maximum_teams==2);}\n /* Ordinary Slayer/explicit changed map and limits remain the latest actual room. */\n s=make_room(2,"levels\\\\test\\\\hangemhigh\\\\hangemhigh");strcpy(s.game.variant.label,"Slayer");s.game.variant.universal_variant.score_to_win=25;s.game.variant_options.no_map_weapons=0;s.game.variant_options.primary_weapon=1;s.game.minimum_players=1;s.game.maximum_players=8;wanted=s.game;network_game_server_capture_multiplayer_round(&s,&held);stale_playlist(&s);network_game_server_restore_multiplayer_round(&s,&held);CHECK(!memcmp(&s.game.variant,&wanted.variant,sizeof(wanted.variant)));CHECK(!strcmp(s.game.map.name,wanted.map.name));CHECK(!memcmp(&s.game.variant_options,&wanted.variant_options,sizeof(wanted.variant_options)));CHECK(s.game.minimum_players==1&&s.game.maximum_players==8);\n /* Co-op and non-postgame startup are not captured/restored. */\n s=make_room(0,"a50");network_game_server_capture_multiplayer_round(&s,&held);CHECK(!held.captured);strcpy(s.game.map.name,"b30");s.game.maximum_players=16;s.game.variant_options.friendly_fire=2;wanted=s.game;int oldmirrors=mirrors;network_game_server_restore_multiplayer_round(&s,&held);CHECK(!memcmp(&s.game,&wanted,sizeof(wanted))&&mirrors==oldmirrors);\n s=make_room(2,"bloodgulch");s.state=1;network_game_server_capture_multiplayer_round(&s,&held);CHECK(!held.captured);stale_playlist(&s);wanted=s.game;network_game_server_restore_multiplayer_round(&s,&held);CHECK(!memcmp(&s.game,&wanted,sizeof(wanted))&&mirrors==oldmirrors);\n s=make_room(6,"unsupported");network_game_server_capture_multiplayer_round(&s,&held);CHECK(!held.captured);\n printf("%d actual production round-settings checks PASS\\n",checks);return 0;}\n'
with tempfile.TemporaryDirectory(prefix='halo-round-settings-') as tmp:
    source=pathlib.Path(tmp)/'test.c';exe=pathlib.Path(tmp)/'test';source.write_text(PREFIX+text[start:end]+CHECKS)
    cmd=[a.cc,'-std=c11','-fshort-wchar','-Wall','-Wextra','-Werror']
    if a.m32:cmd+=['-m32','-malign-double']
    if a.sanitizers:cmd+=['-fsanitize=address,undefined']
    if a.omit_restore:cmd+=['-DOMIT_RESTORE']
    cmd+=[str(source),'-o',str(exe)];subprocess.run(cmd,check=True)
    result=subprocess.run([str(exe)],capture_output=True,text=True);sys.stdout.write(result.stdout);sys.stderr.write(result.stderr);sys.exit(result.returncode)
